<h4 class="mb-3">Returns &amp; Exchanges</h4>
<form class="row g-2 mb-3" method="get"><input type="hidden" name="r" value="pos/returns"><div class="col-md-5"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search original invoice no, customer name or phone" autofocus></div><div class="col-auto"><button class="btn btn-primary"><i class="bi bi-search"></i> Find invoice</button></div></form>
<?php if ($q !== ''): ?><div class="card mb-3"><table class="table table-sm mb-0"><tbody><?php foreach ($found as $f): ?><tr><td><?= e($f['invoice_no']) ?></td><td><?= e(fmt_date($f['sale_date'], 'd M Y')) ?></td><td><?= e($f['customer']) ?></td><td class="text-end"><?= number_format($f['total'], 2) ?></td><td><?= badge($f['status']) ?></td><td class="text-end"><?php if ($f['status'] === 'completed'): ?><a class="btn btn-sm btn-warning" href="<?= url('pos/return_form', ['sale_id' => $f['id']]) ?>">Return / exchange</a><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$found): ?><tr><td class="text-center text-muted py-3">No matching invoices.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?>
<div class="card"><div class="card-header">Recent returns</div><table class="table table-sm mb-0"><tbody><?php foreach ($recent as $r): ?><tr><td><?= e($r['return_no']) ?></td><td><a href="<?= url('pos/sale', ['id' => $r['sale_id']]) ?>"><?= e($r['invoice_no']) ?></a></td><td><?= e(fmt_date($r['return_date'], 'd M H:i')) ?></td><td><?= e($r['refund_method']) ?><?= $r['refund_method'] === 'exchange' ? ($r['exchange_used'] ? ' (used)' : ' (open)') : '' ?></td><td class="text-end"><?= number_format($r['total_refund'], 2) ?></td><td><?= e($r['reason']) ?></td></tr><?php endforeach; ?><?php if (!$recent): ?><tr><td class="text-muted text-center py-3">None.</td></tr><?php endif; ?></tbody></table></div>
